  // 确保即使释放 `b` 抛出异常，`a` 也能被释放
  await using a = ..., b = ...;
  ...
  ```
- 非阻塞内存/IO 应用：
  ```js
  import { ReaderWriterLock } from "...";
  const lock = new ReaderWriterLock();

  export async function readData() {
    // 等待未完成的写入者并获取读锁
    using lockHandle = await lock.read();
    ... // 任意数量的读者
    await ...;
    ... // `await` 后仍持有读锁
  } // 释放读锁

  export async function writeData(data) {
    // 等待所有读者并获取写锁
    using lockHandle = await lock.write();
    ... // 仅一个写入者
    await ...;
    ... // `await` 后仍持有写锁
  } // 释放写锁
  ```
- 与 [固定布局对象提案](https://github.com/tc39/proposal-structs) 和 `shared struct` 结合使用的潜力：
  ```js
  // main.js
  shared struct class SharedData {
    ready = false;
    processed = false;
  }

  const worker = new Worker('worker.js');
  const m = new Atomics.Mutex();
  const cv = new Atomics.ConditionVariable();
  const data = new SharedData();
  worker.postMessage({ m, cv, data });

  // 发送数据给 worker
  {
    // 等待 main 能获取 'm' 上的锁
    using lck = m.lock();

    // 为 worker 标记数据
    data.ready = true;
    console.log("main is ready");

  } // 解锁 'm'

  // 通知可能正在等待的 worker
  cv.notifyOne();

  {
    // 重新获取 'm' 上的锁
    using lck = m.lock();

    // 释放 'm' 上的锁并等待 worker 完成处理
    cv.wait(m, () => data.processed);

  } // 解锁 'm'
  ```

  ```js
  // worker.js
  onmessage = function (e) {
    const { m, cv, data } = e.data;

    {
      // 等待 worker 能够获取 'm' 上的锁
      using lck = m.lock();

      // 释放 'm' 上的锁并等待 main() 发送数据
      cv.wait(m, () => data.ready);

      // 等待后我们再次拥有 'm' 上的锁
      console.log("worker thread is processing data");

      // 发送数据回 main
      data.processed = true;
      console.log("worker thread is done");

    } // 解锁 'm'
  }
  ```

